"""Fold the years regenerated by build_map_payload.py into map_src/, keeping the hand-edited JS.

    python build_map_payload.py 2014 2015 2022 2023 2024 2025
    python merge_payload.py                       # reads cache/_payload_probe.html
    python build_pix_wide.py 2014 ... 2025        # widen the regenerated years' detection grids
    python build_snapshot_bands.py 2014 ... 2025  # 12 h growth bands for the regenerated years
    python map_tool.py join

For every regenerated year the notebook's payload gets the same post-processing the existing years went
through (split_allfires_payload.py, split_sim_payload.py): per/ign/sim split into the pyroCb-linked part and
the lazily loaded "All fire activity" part, nb2 emptied. `goesq` (GOES time series, network job) is kept
from the previous payload for years that had one. Global constants in tail.html are merged: YEARS/YCOL for
all years, MONTH_COUNTS and SEARCH per year, SPREAD_CLAMP recomputed over every year's spread series,
DOY window widened if a new year needs it.
"""
from __future__ import annotations

import base64
import gzip
import json
import re
import shutil
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import split_allfires_payload as SA          # noqa: E402  (split(), COARSE_*; its main() is not run)
from pyrocb import spread as SP              # noqa: E402

PROBE = HERE / "cache" / "_payload_probe.html"
DATA = HERE / "map_src" / "data.json"
TAIL = HERE / "map_src" / "tail.html"
MARK = "const DATA="


def unpack(b):
    return json.loads(gzip.decompress(base64.b64decode(b)).decode())


def pack(o):
    raw = json.dumps(o, separators=(",", ":")).encode()
    return base64.b64encode(gzip.compress(raw, 9)).decode()


def _decode_after(text, key):
    i = text.index(key) + len(key)
    v, end = json.JSONDecoder().raw_decode(text[i:])
    return v, i, i + end


def postprocess(d: dict) -> dict:
    """split_allfires_payload + split_sim_payload for one year's payload."""
    for key, coarsen in (("per", True), ("ign", False)):
        keep, rest = SA.split(unpack(d[key]), coarsen)
        d[key], d[key + "All"] = pack(keep), pack(rest)
    linked = {str(f["properties"]["mergid"]) for f in unpack(d["per"])["features"]}
    sim = unpack(d["sim"])
    d["sim"] = pack({k: v for k, v in sim.items() if k in linked})
    d["simAll"] = pack({k: v for k, v in sim.items() if k not in linked})
    d["nb2"] = pack({"type": "FeatureCollection", "features": []})
    return d


def year_colours(years):
    from matplotlib import colormaps
    from matplotlib.colors import to_hex
    cm = colormaps["RdYlBu_r"]
    n = len(years)
    return {str(y): to_hex(cm(i / (n - 1))) for i, y in enumerate(years)}


def main():
    probe = PROBE.read_text(encoding="utf-8")
    new, _, _ = _decode_after(probe, MARK)
    p_mc, _, _ = _decode_after(probe, "MONTH_COUNTS=")
    p_search, _, _ = _decode_after(probe, "SEARCH=")
    p_doy0 = int(re.search(r"const DOY0=(\d+)", probe).group(1))
    p_doy1 = int(re.search(r"DOY1=(\d+)", probe).group(1))

    data = json.loads(DATA.read_text(encoding="utf-8"))
    bak = DATA.with_suffix(".json.pre_ext")
    if not bak.exists():
        shutil.copyfile(DATA, bak)
    for y, d in sorted(new.items()):
        old = data.get(y, {})
        d = postprocess(d)
        if "goesq" in old:
            d["goesq"] = old["goesq"]
        data[y] = d
        npcb = len(unpack(d["pcb"])["features"])
        print(f"  {y}: {npcb} pyroCb, keys {sorted(d)}", flush=True)
    years = sorted(int(y) for y in data)

    tail = TAIL.read_text(encoding="utf-8")
    TAIL.with_suffix(".html.pre_ext").exists() or shutil.copyfile(TAIL, TAIL.with_suffix(".html.pre_ext"))
    # line 1: YEARS / YCOL
    _, a, b = _decode_after(tail, ", YEARS=")
    tail = tail[:a] + json.dumps(years) + tail[b:]
    _, a, b = _decode_after(tail, "YCOL=")
    tail = tail[:a] + json.dumps(year_colours(years)) + tail[b:]
    # MONTH_COUNTS / SEARCH: per-year merge
    mc, a, b = _decode_after(tail, "MONTH_COUNTS=")
    mc.update(p_mc)
    tail = tail[:a] + json.dumps({k: mc[k] for k in sorted(mc)}) + tail[b:]
    se, a, b = _decode_after(tail, "SEARCH=")
    regen = {int(y) for y in new}
    se = [r for r in se if int(r["y"]) not in regen] + p_search
    se.sort(key=lambda r: (r["y"], r.get("dt") or "", r["id"]))
    tail = tail[:a] + json.dumps(se) + tail[b:]
    # SPREAD_CLAMP over every year's spread series
    spr = {y: unpack(data[y]["spr"]) for y in data}
    _, a, b = _decode_after(tail, "const SPREAD_CLAMP=")
    tail = tail[:a] + json.dumps(SP.clamp(spr)) + tail[b:]
    # DOY window: only ever widen
    m = re.search(r"const DOY0=(\d+), DOY1=(\d+)", tail)
    d0, d1 = min(int(m.group(1)), p_doy0), max(int(m.group(2)), p_doy1)
    tail = tail[:m.start()] + f"const DOY0={d0}, DOY1={d1}" + tail[m.end():]

    DATA.write_text(json.dumps(data, separators=(",", ":")), encoding="utf-8", newline="\n")
    TAIL.write_text(tail, encoding="utf-8", newline="\n")
    print(f"merged {sorted(new)} -> data.json ({DATA.stat().st_size / 1e6:.1f} MB); YEARS {years}; "
          f"DOY {d0}-{d1}; SEARCH {len(se)} events. Backups: *.pre_ext")


if __name__ == "__main__":
    main()
